AgentBenchmarkSuite parseAgentBenchmarkSuite(const V& value){AgentBenchmarkSuite suite;suite.id=word(value,"id");suite.version=positive(value,"version",1);const auto& cases=need(value,"cases");if(cases.t!=V::Arr||cases.arr.empty())throw std::runtime_error("Benchmark cases must be a nonempty array");std::set<std::string> ids;for(const auto& row:cases.arr){AgentBenchmarkCase test;test.id=word(row,"id");if(!ids.insert(test.id).second)throw std::runtime_error("Duplicate benchmark case");test.version=positive(row,"version",1);test.category=word(row,"category");test.brief=word(row,"brief");test.baseline=need(row,"baseline");test.reference=need(row,"reference");test.checks=need(row,"checks");if(auto rejected=row.find("rejected_commands")){if(rejected->t!=V::Arr)throw std::runtime_error("Invalid rejection fixture");test.rejectedCommands=*rejected;}if(test.baseline.t!=V::Arr||test.reference.t!=V::Arr||test.reference.arr.empty()||test.checks.t!=V::Arr||test.checks.arr.empty())throw std::runtime_error("Invalid benchmark baseline/reference/checks");for(const auto& check:test.checks.arr){word(check,"id");const auto& query=need(check,"query");word(query,"tool");word(query,"path");if(need(query,"args").t!=V::Obj)throw std::runtime_error("Invalid benchmark query args");need(check,"equals");if(auto tolerance=check.find("absolute_tolerance"))if(tolerance->t!=V::Num||tolerance->num<0||!std::isfinite(tolerance->num))throw std::runtime_error("Invalid benchmark tolerance");}suite.cases.push_back(test);}return suite;}
