V preflightAgentBenchmark(const AgentBenchmarkSuite& suite){V report=V::makeObj(),rows=V::makeArr();for(const auto& test:suite.cases){V row=V::makeObj();row.set("case",V::makeStr(test.id));AgentSession session;session.suppressIterationHistory();try{if(!test.baseline.arr.empty())apply(session,test.baseline);auto rejection=rejectionProbe(session,test);row.set("initial_rejection",rejection);apply(session,test.reference);auto checks=inspect(session,test.checks);row.set("checks",checks);row.set("passed",V::makeBool(allPassed(checks)&&need(rejection,"passed").b));}catch(const std::exception& e){row.set("error",V::makeStr(e.what()));row.set("passed",V::makeBool(false));}rows.arr.push_back(row);}report.set("passed",V::makeBool(allPassed(rows)));report.set("cases",rows);report.set("suite",V::makeStr(suite.id));report.set("type",V::makeStr("native_reference_preflight"));return report;}
